function groupName(r){const key=r.parent_series_id||r.series_id;if(key==='total')return text('Alle leerlingen','All pupils');const migration=state.split.includes('migration_any')?'any':state.split.includes('migration_both')?'both':null;if(migration&&['reference','migration','migration_minus_reference'].includes(key)){const names=migration==='any'?{reference:text('Beide ouders in toetsland geboren','Both parents born in assessment country'),migration:text('Eén of beide ouders in buitenland geboren','One or both parents born abroad')}:{reference:text('Ten minste één ouder in toetsland geboren','At least one parent born in assessment country'),migration:text('Beide ouders in buitenland geboren','Both parents born abroad')};return key==='migration_minus_reference'?text('Verschil: migratie − referentie','Gap: migration − reference'):names[key];}const raw=state.locale==='nl'?r.series_label_nl:r.series_label_en;const mapped=state.dict.seriesLabels?.[key];return raw&&raw!==key?raw:mapped||({total:text('Alle leerlingen','All pupils'),girl:text('Meisjes','Girls'),boy:text('Jongens','Boys'),q1:text('Lage SES','Low SES'),q4:text('Hoge SES','High SES'),always_almost:text('Thuistaal (bijna) altijd toetstaal','Home language (almost) always test language'),sometimes_never:text('Thuistaal soms / nooit toetstaal','Home language sometimes / never test language')})[key]||key;}
