function renderRelease(){
 const release=state.manifest?.review_release,notice=$('#releaseNotice');
 notice.hidden=!release;
 if(release)notice.innerHTML=`<strong>${text('Tussenstand','Work in progress')} · ${esc(release.date)}</strong> ${text('Gecontroleerde resultaten staan klaar. Ontbrekende meetpunten blijven open; nieuwe resultaten worden na controle toegevoegd.','Verified results are available. Missing points remain open; new results are added after review.')}`;
 if(release?.reference_policy==='AVAILABLE_CASES_PROVISIONAL')notice.innerHTML=`<strong>${text('Tijdelijke vergelijkingen','Provisional comparisons')}</strong> ${text('We gebruiken de beschikbare resultaten. De landenbasis kan per meetjaar en groep verschillen; volledigheid en definitieve controle volgen.','Available results are used. Countries may differ by year and group; completeness and final checks will follow.')}`;
 $('#replicationLink').href=BASE+'info/'+state.locale+'/';
 $('#replicationLink').textContent=text('Methode, bronnen en replicatie','Methods, sources and replication');
}
function renderAvailability(a,f){
 const missing=list(a?.missing_points),panel=$('#availabilityPanel');
 panel.hidden=!missing.length;
 $('#availabilityTitle').textContent=text('Beschikbaarheid','Availability')+' · '+(a?.available_points||0)+' / '+(a?.required_points||0)+' '+text('meetpunten','points');
 const byYear=new Map();for(const p of missing){if(!byYear.has(p.year))byYear.set(p.year,[]);const reason=state.locale==='nl'?p.reason_nl:p.reason_en;byYear.get(p.year).push(groupName({series_id:p.series_id})+(reason?' — '+reason:''));}
 $('#availabilityContent').innerHTML='<p>'+esc(text('Open posities zijn ontbrekende resultaten, geen nulwaarden. De oorspronkelijke jaren en groepen blijven behouden.','Open positions mean missing results, not zero values. The original years and groups are retained.'))+'</p><ul>'+[...byYear].map(([year,groups])=>'<li>'+year+': '+esc(groups.join(', '))+'</li>').join('')+'</ul>';
}

function renderControls(){translate();renderRelease();$('#countrySelect').innerHTML=[...state.countries].sort((a,b)=>countryName(a.code).localeCompare(countryName(b.code),state.locale)).map(c=>option(c.code,countryName(c.code),c.code===state.country)).join('');$('#subjectSelect').innerHTML=SUBJECTS.map(s=>option(s,subjectName(s),s===state.subject)).join('');const c=choices(state.figures,state.subject,state.split);const ordinary=c.splits.filter(s=>!s.startsWith('peers:')), peers=c.splits.filter(s=>s.startsWith('peers:'));$('#splitSelect').innerHTML=ordinary.map(s=>option(s,splitName(s),s===state.split)).join('')+(peers.length?`<optgroup label="${text('Leeromgeving','Learning environment')}">${peers.map(s=>option(s,splitName(s),s===state.split)).join('')}</optgroup>`:'');const rankChoices=state.split.startsWith('peers:')?[]:c.statistics.filter(k=>RANK_RULES[k]);$('#statisticSelect').innerHTML=c.statistics.map(k=>option(k,statisticName(k),!state.rank&&k===state.statistic)).join('')+(rankChoices.length?`<optgroup label="${text('Rangontwikkeling','Rank over time')}">${rankChoices.map(k=>option('rank:'+k,text('Rang · ','Rank · ')+statisticName(k),state.rank&&k===state.statistic)).join('')}</optgroup>`:'');$('#compareToggle').checked=state.compare||state.rank;$('#compareToggle').disabled=state.rank;$('#compareState').textContent=state.rank?text('Rangbasis','Rank basis'):state.compare?text('Aan','On'):text('Uit','Off');$('#referenceSummary').textContent=state.members===null?text('Standaard: rijke OESO-landen','Default: high-income OECD'):text('Eigen selectie','Custom selection');}
const members=()=>state.members===null?list(state.contract?.default_members):state.members;
const temporary=()=>provisional(state.contract);
const contributorNames=r=>(r.rank_basis_members||r.members||[]).map(countryName).join(', ');
function placeholder(reason){const unavailable=reason==='unavailable';return `<div class="status-placeholder"><svg class="placeholder-symbol" viewBox="0 0 48 48" aria-hidden="true"><rect x="9" y="5" width="30" height="38" rx="3" fill="none" stroke="currentColor" stroke-width="1.5"/><path d="M17 16h14M17 23h14M17 30h8" fill="none" stroke="currentColor" stroke-width="1.5"/></svg><h3>${esc(reason==='rank'?text('Geen rang voor deze selectie','No rank for this selection'):unavailable?text('Deze uitsplitsing is niet beschikbaar','This breakdown is unavailable'):text('Geen resultaat voor deze selectie','No result for this selection'))}</h3><p>${esc(reason==='rank'?temporary()?text('De rang verschijnt voor meetpunten met een resultaat van het hoofdland en ten minste één gekozen vergelijkingsland.','Ranks appear for points with a focus-country result and at least one selected reference country.'):text('Een rang vereist voor het hoofdland en ieder gekozen land bruikbare resultaten voor alle getoonde jaren en groepen. Kies passende landen of een andere uitsplitsing.','A rank requires usable results for the focus country and every selected country for all displayed years and groups. Choose eligible countries or another breakdown.'):unavailable?state.unavailableReason||text('De benodigde brongegevens ontbreken voor deze figuur.','The required source data are unavailable for this figure.'):text('Voor deze combinatie zijn geen bruikbare resultaten beschikbaar. Bekijk Beschikbaarheid en Over deze figuur voor de vereiste jaren, groepen en definities.','No usable results are available for this combination. See Availability and About this figure for the required years, groups and definitions.'))}</p><p class="placeholder-context">${esc(countryName(state.country)+' · '+subjectName(state.subject)+' · '+splitName(state.split))}</p></div>`;}
function style(r,i){if(r.series_role==='comparator')return {color:'#727B81',dash:i%2?'7 5':'2 5',shape:'square'};const key=r.parent_series_id||r.series_id;const colors={q1:'#9A6D00',q4:'#6A4C93',girl:'#6A4C93',boy:'#315D8A'};return {color:colors[key]||['#315D8A','#6A4C93','#9A6D00','#2C807F','#587A32'][i%5],dash:i%2?'8 4':'',shape:i%2?'square':'circle'};}
function hasInterval(r){return !state.rank&&r.series_role==='focus'&&r.ci_level===.95&&Number.isFinite(number(r.ci_low))&&Number.isFinite(number(r.ci_high))&&number(r.ci_low)<=number(r.estimate)&&number(r.estimate)<=number(r.ci_high);}
function interval(r){return state.uncertainty&&hasInterval(r);}
function renderUncertainty(){
 const available=state.shown.some(hasInterval),toggle=$('#uncertaintyToggle');
 toggle.disabled=!available;toggle.checked=available&&state.uncertainty;
 $('#uncertaintyLabel').textContent=text('Onzekerheidsmarge','Uncertainty range');
 $('#uncertaintyState').textContent=toggle.checked?text('Aan','On'):text('Uit','Off');
 $('#uncertaintyHelp').textContent=state.rank?text('Niet beschikbaar voor rangen','Not available for ranks'):available?'':text('Geen gecontroleerde marge beschikbaar','No verified range available');
 $('#uncertaintyHelp').hidden=available;
 toggle.title=text('Toon het 95%-betrouwbaarheidsinterval rond de schattingen van het hoofdland.','Show the 95% confidence interval around the focus-country estimates.');
}

function tooltip(r){const contribution=r.comparison_status==='PROVISIONAL'?' · '+text('Voorlopig','Provisional')+' · '+countryCount(r.rank_basis_n||r.comparator_n)+': '+contributorNames(r):'';return `${seriesName(r)} · ${r.year}: ${fmt(r.estimate,2)}${Number.isFinite(number(r.se))?' · SE: '+fmt(r.se,2):''}${interval(r)?' · '+text('95%-betrouwbaarheidsinterval: ','95% confidence interval: ')+fmt(r.ci_low,2)+'–'+fmt(r.ci_high,2):''}${contribution}`;}
function chart(rows,f,exporting=false){const mobile=!exporting&&window.innerWidth<600,W=mobile?360:1120,H=mobile?320:430,pad={l:mobile?54:64,r:mobile?20:208,t:28,b:50};const ys=words(f.required_years).map(Number).sort((a,b)=>a-b);let lo=Math.min(...rows.map(r=>interval(r)?number(r.ci_low):number(r.estimate))),hi=Math.max(...rows.map(r=>interval(r)?number(r.ci_high):number(r.estimate)));const floor=f.unit==='percent'?1:2.5;const margin=Math.max((hi-lo)*.1,floor);const withinLower=lo>=0,withinUpper=hi<=100;lo-=margin;hi+=margin;if(f.unit==='percent'){if(withinLower)lo=Math.max(0,lo);if(withinUpper)hi=Math.min(100,hi);}if(state.rank){lo=1;hi=Math.max(2,members().length+1);}const sx=y=>pad.l+(y-ys[0])/(ys.at(-1)-ys[0]||1)*(W-pad.l-pad.r),sy=v=>pad.t+(state.rank?(v-lo)/(hi-lo):1-(v-lo)/(hi-lo))*(H-pad.t-pad.b);let svg='';const ticks=state.rank?(hi<=8?Array.from({length:hi},(_,i)=>i+1):[...new Set([1,Math.round(hi/4),Math.round(hi/2),Math.round(hi*3/4),hi])]):Array.from({length:5},(_,i)=>lo+(hi-lo)*i/4);
for(const v of ticks)svg+=`<line class="grid-line" x1="${pad.l}" x2="${W-pad.r}" y1="${sy(v)}" y2="${sy(v)}"/><text class="axis-label" x="${pad.l-12}" y="${sy(v)+5}" text-anchor="end">${esc(fmt(v,state.rank?0:1))}</text>`;
for(const [i,y]of ys.entries()){if(mobile&&ys.length>6&&i%2&&i!==ys.length-1)continue;svg+=`<text class="axis-label" x="${sx(y)}" y="${H-16}" text-anchor="middle">${y}</text>`;}
const groups=new Map();rows.forEach(r=>{const k=r.series_id;if(!groups.has(k))groups.set(k,[]);groups.get(k).push(r);});let idx=0,legend='',ends=[];
for(const [key,g]of groups){g.sort((a,b)=>a.year-b.year);const st=style(g[0],idx++);let d='',prev=null;for(const r of g){const br=breakBetween(prev,r,f)||(prev&&groupName(prev)!==groupName(r));d+=(prev&&!br?' L ':' M ')+sx(r.year)+' '+sy(r.estimate);prev=r;}svg+=`<path class="series-line" d="${d}" stroke="${st.color}" stroke-dasharray="${st.dash}"/>`;for(const r of g){const x=sx(r.year),y=sy(r.estimate);if(interval(r))svg+=`<path class="ci-line" d="M${x} ${sy(r.ci_low)}V${sy(r.ci_high)} M${x-3} ${sy(r.ci_low)}h6 M${x-3} ${sy(r.ci_high)}h6" stroke="${st.color}" fill="none"/>`;const attrs=`class="data-point" tabindex="0" role="img" aria-label="${esc(tooltip(r))}" data-tooltip="${esc(tooltip(r))}" fill="${st.color}"`;svg+=st.shape==='square'?`<rect ${attrs} x="${x-4}" y="${y-4}" width="8" height="8"/>`:`<circle ${attrs} cx="${x}" cy="${y}" r="4.5"/>`;}
const last=g.at(-1);ends.push({y:sy(last.estimate),actual:sy(last.estimate),label:seriesName(last),style:st});legend+=`<span class="legend-item"><span class="legend-line" style="border-color:${st.color};border-top-style:${st.dash?'dashed':'solid'}"></span>${esc(seriesName(last))}</span>`;}
if(!mobile&&groups.size<=4){ends.sort((a,b)=>a.y-b.y);for(let i=1;i<ends.length;i++)ends[i].y=Math.max(ends[i].y,ends[i-1].y+24);const overflow=Math.max(0,ends.at(-1).y-(H-pad.b));ends.forEach(e=>e.y-=overflow);for(const e of ends)svg+=`<path d="M${W-pad.r+4} ${e.actual} L${W-pad.r+14} ${e.y}" fill="none" stroke="${e.style.color}"/><text class="direct-label" x="${W-pad.r+19}" y="${e.y+5}" fill="${e.style.color}">${esc(e.label.length>28?e.label.slice(0,27)+'…':e.label)}</text>`;}
return `<div class="chart-wrap"><div class="chart-legend">${legend}</div><svg xmlns="http://www.w3.org/2000/svg" class="time-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc($('#figureHeading').textContent)}" data-y-min="${lo}" data-y-max="${hi}" data-axis-policy="${state.rank?'rank':'dynamic'}"><title>${esc($('#figureHeading').textContent)}</title>${svg}</svg><div id="chartTooltip" class="chart-tooltip" hidden></div></div><details class="data-details"><summary>${text('Bekijk de gegevens bij deze figuur','View this figure’s data')}</summary><div class="data-table-wrap"><table><thead><tr><th>${text('Jaar','Year')}</th><th>${text('Reeks','Series')}</th><th>${text('Waarde','Value')}</th><th>SE</th><th>N</th><th>95% interval</th>${rows.some(r=>r.comparison_status==='PROVISIONAL')?'<th>'+text('Landen in dit punt','Countries in this point')+'</th><th>'+text('Niet gebruikt','Not used')+'</th>':''}</tr></thead><tbody>${rows.map(r=>`<tr><td>${r.year}</td><td>${esc(seriesName(r))}</td><td>${fmt(r.estimate,2)}</td><td>${fmt(r.se,2)}</td><td>${fmt(r.n_unweighted,0)}</td><td>${hasInterval(r)?fmt(r.ci_low,2)+'–'+fmt(r.ci_high,2):'—'}</td>${rows.some(x=>x.comparison_status==='PROVISIONAL')?'<td>'+esc(r.comparison_status==='PROVISIONAL'?countryCount(r.rank_basis_n||r.comparator_n)+': '+contributorNames(r):'—')+'</td><td>'+esc((r.excluded_members||[]).map(countryName).join(', ')||'—')+'</td>':''}</tr>`).join('')}</tbody></table></div></details>`;}
function bindTooltips(){const tt=$('#chartTooltip');if(!tt)return;for(const el of $$('.data-point')){const show=e=>{tt.textContent=el.dataset.tooltip;tt.hidden=false;const box=el.closest('.chart-wrap').getBoundingClientRect();tt.style.left=Math.max(4,Math.min((e.clientX||box.left+40)-box.left+12,box.width-270))+'px';tt.style.top=Math.max(4,(e.clientY||box.top+30)-box.top+12)+'px';};el.addEventListener('pointerenter',show);el.addEventListener('focus',show);el.addEventListener('click',show);el.addEventListener('pointerleave',()=>tt.hidden=true);el.addEventListener('blur',()=>tt.hidden=true);}}
function methodContent(f){const years=words(f.required_years),rule=RANK_RULES[state.statistic];return `${temporary()?'<p><strong>'+text('Voorlopige vergelijking.','Provisional comparison.')+'</strong> '+text('Per meetjaar en groep gebruiken we beschikbare landen met gelijke gewichten. De tabel toont de gebruikte en weggelaten landen. Ook een rangbasis kan wisselen; een verandering is daardoor niet uitsluitend een verandering van prestaties. De stippellijn verbindt opeenvolgende beschikbare meetjaren, ook bij een veranderende landensamenstelling. Ontbrekende meetjaren en definitiewijzigingen onderbreken de lijn; bij rangen onderbreekt ook een gewijzigde rangbasis. Bekende verschillen tussen meisjes en meisjes + other worden niet samengevoegd. De volledige controle volgt na afronding van de resultaten.','Available countries receive equal weight within each year and group. The table lists contributing and omitted countries. Rank bases may change too, so a change need not reflect performance alone. The dashed reference line connects adjacent available survey waves, including when membership changes. Missing waves and definition changes break the line; changing rank bases also break rank lines. Known differences between girls and girls + other are not pooled. Full review follows completion of the results.')+'</p>':''}<p>${text('Schattingen gebruiken de officiële steekproefgewichten, plausible values en het bijbehorende replicatieontwerp. De figuur toont alleen gecontroleerde resultaten. De tabel en tooltips vermelden de standaardfout (SE). Met ‘Onzekerheidsmarge’ toon je voor het hoofdland een 95%-betrouwbaarheidsinterval: schatting ± 1,96 × de gecontroleerde standaardfout. Een breder interval betekent een minder precieze schatting. Dit is geen spreiding tussen leerlingen en omvat niet alle mogelijke vertekeningen. De normale benadering kan bij percentages buiten 0–100 vallen; we kappen grenzen niet stilzwijgend af. Intervaloverlap is geen toets van een verschil.','Estimates use official sampling weights, plausible values and the corresponding replication design. The figure shows verified results only. The table and tooltips report the standard error (SE). ‘Uncertainty range’ shows a 95% confidence interval for the focus country: estimate ± 1.96 × the verified standard error. A wider interval means a less precise estimate. This is not variation between pupils and does not cover every possible source of bias. The normal approximation can extend beyond 0–100 for percentages; bounds are not silently clipped. Interval overlap is not a test of a difference.')}</p><p>${state.rank?text('Rang 1 betekent hier: ','Rank 1 here means: ')+(rule.transform==='absolute'?text('de kleinste absolute groepskloof.','the smallest absolute group gap.'):rule.direction==='ascending'?text('de laagste waarde.','the lowest value.'):text('de hoogste waarde.','the highest value.'))+' '+text('Gelijke waarden krijgen de gemiddelde rang. Punt-rangen zijn geen toets van significante verschillen. De vergelijkingsgroep wordt niet geplot.','Ties receive average ranks. Point ranks do not establish significant differences. The reference group is not plotted.'):temporary()?text('De beschikbare landen wegen ieder even zwaar. Er wordt geen betrouwbaarheidsinterval voor het groepsgemiddelde afgeleid.','Available countries each receive equal weight. No confidence interval is derived for the group average.'):text('De vergelijkingsgroep is een ongewogen gemiddelde van landen, zonder betrouwbaarheidsinterval. De samenstelling blijft gelijk over alle meetjaren en groepen.','The reference is an equal-country average without a confidence interval. Membership stays constant over all years and groups.')}</p><p>${text('Kleine of onvoldoende gedekte analysegroepen worden niet geplot. Ieder benodigd onderdeel moet ten minste 30 leerlingen en, waar schoolidentificaties beschikbaar zijn, ten minste vijf waargenomen scholen bevatten. Ontbrekende brongegevens, onvergelijkbare definities en deze kwaliteitsgrenzen kunnen punten of vergelijkingslanden uitsluiten. Een ontbrekend punt is nooit een nulwaarde.','Small or insufficiently covered analysis groups are not plotted. Each required component must contain at least 30 pupils and, where school identifiers are available, at least five observed schools. Missing source data, incompatible definitions and these quality thresholds can exclude points or comparison countries. A missing point is never a zero value.')}</p><dl class="method-grid"><div><dt>${text('Populatie en bron','Population and source')}</dt><dd>${esc(subjectName(state.subject))} · ${esc(f.survey)}${f.age==='age10'?' · '+text('internationaal vierde leerjaar = Nederlandse groep 6','international fourth grade'):''}</dd></div><div><dt>${text('Periode en eenheid','Period and unit')}</dt><dd>${esc(years.join(', '))} · ${esc(state.rank?text('rang','rank'):unitName(f.unit))}</dd></div><div><dt>${text('Vergelijkingsgroep','Reference group')}</dt><dd>${esc(members().map(countryName).join(', ')||text('Geen passende landen beschikbaar','No eligible countries available'))}</dd></div><div><dt>${text('Definitie','Definition')}</dt><dd>${esc(state.locale==='nl'?f.subtitle_nl:f.subtitle_en)}</dd></div></dl><p>${text('Download ‘Data + herkomst’ voor de resultaat-, bron- en codevingerafdrukken, exacte selectie en gebruikte afleiding.','Download “Data + provenance” for result, source and code fingerprints, the exact selection and the derivation used.')}</p>`;}
async function refresh(){const run=++epoch;Object.assign(state,normalizeSelection(state.figures,state));renderControls();const selectedFigure=selectFigure(state.figures,state);state.contract=selectedFigure?list(state.references.figures).find(r=>r.focus===state.country&&r.figure_id===selectedFigure.figure_id)||null:null;let f=focusFigure(selectedFigure,state.contract);state.currentFigure=f;state.shown=[];renderUncertainty();$('#editReference').disabled=true;$('.figure-shell').setAttribute('aria-busy','true');$('#figureHeading').textContent=(state.rank?text('Rang · ','Rank · '):'')+statisticName(state.statistic)+' — '+subjectName(state.subject);$('#measureLabel').textContent=countryName(state.country)+' · '+splitName(state.split);$('#figureSubtitle').textContent=f?`${f.survey} · ${text('Meetjaren','Survey years')} ${words(f.required_years).join(', ')}`:'';$('#chartStage').innerHTML=placeholder('pending');$('#comparisonNotice').hidden=true;for(const id of ['downloadData','downloadFigure','downloadProvenance'])$('#'+id).disabled=true;
try{if(!f)throw new Error('NO_APPROVED_FIGURE');await countryPayload(state.country);if(run!==epoch)return;state.contract=list(state.references.figures).find(r=>r.focus===state.country&&r.figure_id===selectedFigure.figure_id)||null;f=focusFigure(selectedFigure,state.contract);state.currentFigure=f;$('#figureSubtitle').textContent=`${f.survey} · ${text('Meetjaren','Survey years')} ${words(f.required_years).join(', ')}`;const rows=list(state.payloads[state.country].records).filter(r=>r.figure_id===f.figure_id&&r.series_role!=='comparator');state.records=rows;const a=list(state.availability[state.country]?.figures).find(r=>r.figure_id===f.figure_id);state.contract=list(state.references.figures).find(r=>r.focus===state.country&&r.figure_id===f.figure_id)||null;state.unavailableReason=a?(state.locale==='nl'?a.reason_nl:a.reason_en):'';const good=a?.display_state==='VALIDATED'&&completeRows(rows,f);let shown=state.rank?[]:displayableRows(rows,f,a),comparisonProblem='';renderAvailability(a,f);
if(state.rank||state.compare){const status=referenceStatus(state.contract,state.country,members());if(!status.ok)comparisonProblem=status.reason;else{try{await Promise.all(members().map(countryPayload));if(run!==epoch)return;if(state.rank&&(good||temporary()))shown=rankRows(f,state.statistic,state.country,members(),state.payloads,state.contract,state.other);else if(good||temporary()){const reference=referenceRows(f,state.country,members(),state.payloads,state.contract);shown=[...shown,...reference];if(!reference.length)comparisonProblem='available_missing';};}catch(error){comparisonProblem='incomplete';console.warn(error.message);}}}
if(run!==epoch)return;if(state.rank&&comparisonProblem)shown=[];shown=presentationRows(shown,f,state.rank);state.shown=shown;renderUncertainty();$('#chartStage').innerHTML=shown.length?chart(shown,f):placeholder(state.rank?'rank':a?.display_state==='UNAVAILABLE'?'unavailable':'pending');bindTooltips();$('#figureStatus').textContent=shown.length&&temporary()&&(state.compare||state.rank)?text('Voorlopige vergelijking','Provisional comparison'):shown.length?(a?.display_state==='PARTIAL'?text('Deels beschikbaar','Partly available'):text('Gecontroleerde resultaten','Verified results')):text('Niet beschikbaar voor deze selectie','Unavailable for this selection');$('#figureStatus').dataset.state=shown.length?(temporary()&&(state.compare||state.rank)?'provisional':'ready'):'pending';$('#comparisonNotice').hidden=!comparisonProblem;$('#comparisonNotice').textContent=comparisonProblem==='available_missing'?text('Er zijn voor deze figuur geen bruikbare vergelijkingspunten. Kies andere landen of een andere uitsplitsing.','No usable comparison points are available for this figure. Choose other countries or another breakdown.'):comparisonProblem==='empty'?text('Geen landen geselecteerd. Kies landen voor de vergelijking.','No countries selected. Choose countries for comparison.'):comparisonProblem==='ineligible'?text('Je selectie bevat landen die niet meer passen bij deze figuur. Pas de landenkeuze aan; de periode en groepen blijven behouden.','Your selection contains countries that do not match this figure. Update the selection; years and groups are preserved.'):comparisonProblem==='coverage'?text('Geen land heeft de volledige passende dekking voor deze vergelijking. Open Landen kiezen voor de ontbrekende jaren.','No country has complete matching coverage for this comparison. Open Choose countries to see the missing years.'):comparisonProblem==='admission'?text('Voor deze leeftijd en uitkomst zijn minder dan drie vergelijkbare meetgolven beschikbaar. Kies een andere uitkomst of een ander hoofdland.','Fewer than three comparable waves are available for this age and outcome. Choose another outcome or focus country.'):comparisonProblem==='focus_core'?text('De volledige basisreeks van het hoofdland ontbreekt voor deze vergelijking. De gekozen periode blijft behouden.','The focus country lacks the complete core series required for this comparison. The selected period is retained.'):comparisonProblem==='focus_view'?text('Het hoofdland heeft niet voor alle vereiste jaren en groepen bruikbare resultaten. Daarom is voor deze figuur geen volledige vergelijking mogelijk.','The focus country lacks usable results for some required years and groups. A complete comparison is therefore unavailable for this figure.'):text('De internationale vergelijking voldoet niet aan de vereiste dekking van jaren, groepen en definities. Kies een andere uitsplitsing of landenselectie.','The international comparison does not meet the required coverage of years, groups and definitions. Choose another breakdown or country selection.');$('#referenceSummary').textContent=(state.members===null?text('Standaard','Default'):text('Eigen selectie','Custom'))+' · '+countryCount(members().length);
if(temporary()&&(state.compare||state.rank)&&!comparisonProblem){$('#comparisonNotice').hidden=false;$('#comparisonNotice').textContent=state.rank?text('De beschikbare landen bepalen de rang per meetpunt. Een gewijzigde rangbasis onderbreekt de lijn; de landen staan in de gegevenstabel. De volledige controle volgt.','Available countries determine each point’s rank. A changing rank basis breaks the line; countries are listed in the data table. Full review will follow.'):text('De stippellijn verbindt beschikbare meetjaren. De gebruikte landen kunnen per meetjaar en groep verschillen; bekijk de landen per punt in de gegevenstabel. De volledige controle volgt.','The dashed line connects available survey waves. Contributing countries may differ by year and group; see each point’s countries in the data table. Full review will follow.');}
const pooled=state.split==='gender'?rows.filter(r=>/other/i.test(r.series_label_nl||'')):[];$('#definitionNote').textContent=pooled.length?text('Let op: in ','Note: in ')+[...new Set(pooled.map(r=>r.year))].join(', ')+text(' is ‘meisjes + other’ de beschikbare categorie. Een definitiewijziging wordt niet met een doorlopende lijn verbonden.',' “girls + other” is the available category. A definition change is not connected by a continuous line.'):state.split.startsWith('peers:')?text('Peers worden berekend zonder de leerling zelf: bij PIRLS/TIMSS binnen de klas, bij PISA binnen het onderwijsprogramma op de school. Schoolgenoten omvatten de hele school. Dit is een beschrijvende samenhang, geen causaal peereffect.','Peers exclude the pupil themself: within the class for PIRLS/TIMSS and within the school programme for PISA. School peers include the whole school. This is a descriptive association, not a causal peer effect.'):'';$('#figureSource').textContent=text('Bron: ','Source: ')+f.survey+' · '+(state.rank?temporary()?text('Rang binnen beschikbare landen','Rank within available countries'):text('Rang binnen vaste landengroep','Rank within a fixed country set'):f.unit==='percent'?text('Aandeel leerlingen (%)','Share of pupils (%)'):/percentage?_points/.test(f.unit)?text('Procentpunten','Percentage points'):text('Scorepunten','Score points'));if(temporary()&&(state.compare||state.rank))$('#figureSource').textContent+=' · '+text('Voorlopig; landenbasis kan wisselen','Provisional; country coverage may change');$('#methodContent').innerHTML=methodContent(f);for(const id of ['downloadData','downloadFigure','downloadProvenance'])$('#'+id).disabled=!shown.length;$('#appStatus').textContent=$('#figureHeading').textContent+' · '+$('#figureStatus').textContent;
}catch(error){if(run!==epoch)return;$('#figureStatus').textContent=text('Laden niet gelukt','Unable to load');$('#chartStage').innerHTML=`<div class="status-placeholder"><h3>${text('Gegevens tijdelijk niet bereikbaar','Data temporarily unavailable')}</h3><p>${text('Ververs de pagina om opnieuw te proberen. Je selectie blijft in de link bewaard.','Refresh the page to retry. Your selection is saved in the link.')}</p></div>`;console.error(error);}finally{if(run===epoch){$('#editReference').disabled=!state.contract;$('.figure-shell').setAttribute('aria-busy','false');history.replaceState(null,'',location.pathname+selectionSearch(state));}}}
function referenceReason(info,code,defaults){
 if(info.reason==='provisional')return (defaults.includes(code)?text('Standaardgroep · ','Default group · '):'')+String(info.detail?.available_points||0)+' '+text('meetpunten beschikbaar · voorlopig','points available · provisional');
 if(info.reason==='available_missing')return text('Geen bruikbare resultaten voor deze figuur','No usable results for this figure');
 if(info.allowed)return defaults.includes(code)?text('Standaardgroep · volledige dekking','Default group · complete coverage'):text('Volledige passende dekking','Complete comparable coverage');
 if(info.reason==='focus')return text('Hoofdland · uitgesloten van eigen groep','Focus country · excluded from own group');
 if(info.reason==='focus_core')return text('De volledige basisreeks van het hoofdland ontbreekt','The focus country’s complete core series is unavailable');
 if(info.reason==='focus_view')return text('Deze figuur mist vereiste meetpunten van het hoofdland','This figure lacks required focus-country points');
 if(info.reason==='admission')return text('Minder dan drie vergelijkbare meetgolven voor deze leeftijd en uitkomst','Fewer than three comparable waves for this age and outcome');
 if(info.reason==='missing'){
  const examples=list(info.detail.missing_examples).map(x=>x.survey+' '+x.year).filter((x,i,a)=>a.indexOf(x)===i);
  return text('Ontbrekende of niet passende dekking: ','Missing or incompatible coverage: ')+examples.join(', ')+(info.detail.missing_cells>examples.length?'…':'');
 }
 return text('Volledige vergelijkbaarheid is niet aangetoond','Complete comparability is not established');
}
function renderReferenceList(){
 const search=$('#countrySearch').value.toLocaleLowerCase(),eligible=list(state.contract?.eligible_members),defaults=list(state.contract?.default_members);
 const countries=[...state.countries].sort((a,b)=>Number(eligible.includes(b.code))-Number(eligible.includes(a.code))||Number(defaults.includes(b.code))-Number(defaults.includes(a.code))||countryName(a.code).localeCompare(countryName(b.code),state.locale)).filter(c=>countryName(c.code).toLocaleLowerCase().includes(search));
 $('#referenceCountries').innerHTML=countries.map(c=>{
  const checked=draftMembers.includes(c.code),info=referenceOption(state.contract,state.country,c.code);
  return `<label class="reference-country ${info.allowed?'':'unavailable'}"><input type="checkbox" value="${c.code}"${checked?' checked':''}${!info.allowed&&!checked?' disabled':''}><span>${esc(countryName(c.code))}<small>${esc(referenceReason(info,c.code,defaults))}</small></span></label>`;
 }).join('')||'<p>'+esc(text('Geen landen gevonden','No countries found'))+'</p>';
 $('#referenceCount').textContent=draftMembers.length+' '+text('geselecteerd','selected')+' · '+eligible.length+' '+text('beschikbaar','available');
 if(draftOther&&!draftMembers.includes(draftOther))draftOther='';
 $('#rankOtherSelect').innerHTML=option('',text('Geen tweede land','No second country'),!draftOther)+draftMembers.map(c=>option(c,countryName(c),draftOther===c)).join('');
 const invalid=draftMembers.some(c=>!eligible.includes(c));
 $('#applyReference').disabled=!draftMembers.length||invalid;
 $('#referenceFeedback').textContent=invalid?text('Verwijder de geselecteerde landen zonder passende dekking.','Remove selected countries without matching coverage.'):!eligible.length?text('Er zijn voor deze selectie nog geen passende landen beschikbaar. Hieronder staat waarom.','No countries currently meet this selection’s requirements. The reasons are listed below.'):!draftMembers.length?text('Kies ten minste één beschikbaar land.','Choose at least one available country.'):'';
}
function openReference(){draftMembers=[...members()];draftDefault=state.members===null;draftOther=state.other;$('#countrySearch').value='';$('#rankOtherGroup').hidden=!state.rank;$('#referenceHelp').textContent=state.rank?text('Deze landen bepalen de rang van het hoofdland. De groep krijgt geen eigen lijn. Alleen landen met volledige passende jaren, groepen en definities zijn selecteerbaar.','These countries determine the focus country’s rank. The group has no line of its own. Only countries with complete matching years, groups and definitions can be selected.'):text('Standaard gebruiken we de passende rijke OESO-landen, zonder het hoofdland. Ieder land telt even zwaar. Landen zonder volledige dekking zijn niet selecteerbaar.','The default uses eligible high-income OECD countries, excluding the focus country. Each country has equal weight. Countries without complete coverage cannot be selected.');if(temporary())$('#referenceHelp').textContent=state.rank?text('Tijdelijk bepalen de beschikbare landen per meetjaar en groep de rang. De landenbasis kan wisselen. De groep krijgt geen eigen lijn; de gebruikte landen staan bij ieder punt.','Temporarily, available countries determine each year and group’s rank. Country coverage may vary. The group has no line of its own; contributors are listed at each point.'):text('Tijdelijk gebruiken we de beschikbare resultaten. Standaard staan de beschikbare rijke OESO-landen aan. Ieder land weegt even zwaar; ontbrekende punten worden overgeslagen en per meetjaar vermeld.','Temporarily, available results are used. Available high-income OECD countries are selected by default. Each country has equal weight; missing points are omitted and reported for each year.');renderReferenceList();$('#referenceDialog').showModal();}
function saveBlob(content,type,name){const u=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);$('#exportMenu').open=false;}
function exportPayload(){return {schema_version:1,selection:{country:state.country,subject:state.subject,split:state.split,statistic:state.statistic,rank:state.rank,compare:state.compare,uncertainty:state.uncertainty,locale:state.locale,other:state.other,members:members()},display_policy:DISPLAY_POLICY,figure:state.currentFigure,result_build:state.manifest||{},reference_contract:state.contract,derivation_version:temporary()?'EXPLORER_AVAILABLE_CASES_PROVISIONAL_V1':'EXPLORER_AGGREGATES_V1',records:state.shown};}
function fileName(ext){return `leerprestaties_${state.country}_${state.currentFigure.figure_id}${state.rank?'_rank':''}.${ext}`;}
async function downloadFigure(){
 // Capture the displayed selection before asynchronous asset reads. A later
 // control change must not relabel an already requested export.
 const payload=JSON.stringify(exportPayload()),name=fileName('svg'),locale=state.locale;
 const heading=$('#figureHeading').textContent,measure=$('#measureLabel').textContent,source=$('#figureSource').textContent;
 const labels=[...new Set(state.shown.map(seriesName))];if(state.shown.some(interval))labels.push(text('Balkjes: 95%-betrouwbaarheidsinterval van het hoofdland','Bars: 95% confidence interval for the focus country'));
 const container=document.createElement('div');container.innerHTML=chart(state.shown,state.currentFigure,true);
 const svg=container.querySelector('svg.time-chart').cloneNode(true);
 try{
  const assets=await Promise.all([`assets/brand/leerprestaties_${locale}.svg`,'assets/brand/fonts.css'].map(async path=>{
   const response=await fetch(BASE+path,{signal:AbortSignal.timeout(15000)});
   if(!response.ok)throw new Error(`Export asset HTTP ${response.status}`);return response.text();
  }));
  const [,,w,h]=svg.getAttribute('viewBox').split(' ').map(Number),height=h+250+Math.ceil(labels.length/2)*24;
  svg.setAttribute('xmlns','http://www.w3.org/2000/svg');svg.setAttribute('viewBox',`0 -160 ${w} ${height}`);
  svg.setAttribute('width',String(w));svg.setAttribute('height',String(height));
  const ns='http://www.w3.org/2000/svg',css=document.createElementNS(ns,'style');
  css.textContent=assets[1]+`text{font-family:Oswald,Arial,sans-serif}.axis-label{font-size:16px;fill:#59636A}.direct-label{font-size:15px}.grid-line{stroke:#D8D8D3;stroke-width:1}.series-line{fill:none;stroke-width:2.75}.ci-line{stroke-width:1.1}.data-point{stroke:white;stroke-width:1.6}`;svg.prepend(css);
  const bg=document.createElementNS(ns,'rect');for(const [k,v]of Object.entries({x:0,y:-160,width:w,height,fill:'#FFFFFF'}))bg.setAttribute(k,String(v));svg.prepend(bg);
  const logo=document.createElementNS(ns,'image');logo.setAttribute('href','data:image/svg+xml;charset=utf-8,'+encodeURIComponent(assets[0]));
  for(const [k,v]of Object.entries({x:12,y:-152,width:240,height:56}))logo.setAttribute(k,String(v));svg.append(logo);
  const addText=(x,y,value,size)=>{const t=document.createElementNS(ns,'text');t.setAttribute('x',x);t.setAttribute('y',y);t.setAttribute('font-size',size);t.setAttribute('fill','#17242D');t.textContent=value;svg.append(t);};
  addText(12,-68,heading,24);addText(12,-34,measure,18);addText(12,h+30,source,14);
  labels.forEach((label,i)=>addText(12+(i%2)*w/2,h+56+Math.floor(i/2)*24,label,14));
  const meta=document.createElementNS(ns,'metadata');meta.textContent=payload;svg.append(meta);
  saveBlob(new XMLSerializer().serializeToString(svg),'image/svg+xml',name);
  $('#appStatus').textContent=text('Figuurdownload voorbereid.','Figure download prepared.');
 }catch(error){$('#exportMenu').open=false;$('#appStatus').textContent=text('Download niet gelukt. Probeer het opnieuw.','Download failed. Please retry.');console.error(error);}
}

function bind(){for(const [id,key]of [['countrySelect','country'],['subjectSelect','subject'],['splitSelect','split']])$('#'+id).addEventListener('change',e=>{state[key]=e.target.value;if(key==='country'){state.members=null;state.other='';}const before=state.statistic;const next=normalizeSelection(state.figures,state);$('#selectionNotice').hidden=before===next.statistic;$('#selectionNotice').textContent=text('Bij deze uitsplitsing tonen we: ','This breakdown uses: ')+statisticName(next.statistic)+'.';Object.assign(state,next);refresh();});$('#statisticSelect').addEventListener('change',e=>{state.rank=e.target.value.startsWith('rank:');state.statistic=e.target.value.replace(/^rank:/,'');refresh();});$('#compareToggle').addEventListener('change',e=>{state.compare=e.target.checked;refresh();});$('#uncertaintyToggle').addEventListener('change',e=>{state.uncertainty=e.target.checked;refresh();});$('#localeSelect').addEventListener('change',e=>location.assign(new URL(BASE+e.target.value+'/',location.href).pathname+selectionSearch(state)));$('#editReference').addEventListener('click',openReference);$('#closeReference').addEventListener('click',()=>$('#referenceDialog').close());$('#countrySearch').addEventListener('input',renderReferenceList);$('#referenceCountries').addEventListener('change',e=>{if(e.target.type!=='checkbox')return;draftDefault=false;draftMembers=e.target.checked?[...draftMembers,e.target.value]:draftMembers.filter(c=>c!==e.target.value);renderReferenceList();});$('#restoreReference').addEventListener('click',()=>{draftDefault=true;draftMembers=[...list(state.contract?.default_members)];draftOther='';renderReferenceList();});$('#rankOtherSelect').addEventListener('change',e=>draftOther=e.target.value);$('#referenceForm').addEventListener('submit',e=>{e.preventDefault();if(!referenceStatus(state.contract,state.country,draftMembers).ok)return;state.members=draftDefault?null:[...new Set(draftMembers)].sort();state.other=draftOther;$('#referenceDialog').close();refresh();});$('#copyLink').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(location.href);$('#copyLink').textContent=text('Link gekopieerd','Link copied');}catch{window.prompt(text('Kopieer deze link','Copy this link'),location.href);}});$('#downloadProvenance').addEventListener('click',()=>saveBlob(JSON.stringify(exportPayload(),null,2),'application/json',fileName('json')));$('#downloadData').addEventListener('click',()=>{const fields=[...new Set(state.shown.flatMap(Object.keys))];const q=v=>'"'+String(v&&typeof v==='object'?(Array.isArray(v)&&v.every(x=>typeof x!=='object')?v.join(';'):JSON.stringify(v)):v??'').replaceAll('"','""')+'"';saveBlob('\uFEFF'+[fields.join(','),...state.shown.map(r=>fields.map(k=>q(r[k])).join(','))].join('\r\n'),'text/csv;charset=utf-8',fileName('csv'));});$('#downloadFigure').addEventListener('click',downloadFigure);
for(const b of $$('#questionGrid button'))b.addEventListener('click',()=>{const question=b.dataset.question;const f=state.figures.find(f=>f.question===question&&compatible(f,state.subject));if(f){state.split=splitKey(f);state.statistic=statisticKey(f);state.rank=false;refresh();$('#figureControls').scrollIntoView({behavior:'smooth',block:'start'});}});window.addEventListener('popstate',()=>{Object.assign(state,readSelection(location.search,{}));refresh();});let resize;window.addEventListener('resize',()=>{clearTimeout(resize);resize=setTimeout(()=>{if(state.shown.length){$('#chartStage').innerHTML=chart(state.shown,state.currentFigure);bindChartSafe();}},150);});}
function bindChartSafe(){bindTooltips();}
async function init(){const route=parseRoute(location.pathname);state.locale=route.locale;translate();$('#figureHeading').textContent=text('Resultaten laden…','Loading results…');$('#chartStage').textContent=text('Resultaten laden…','Loading results…');Object.assign(state,readSelection(location.search,state));const [countries,figures,dict,refs,manifest]=await Promise.all([json('data/common42.json'),json('data/figure_registry.json'),json(`locales/${state.locale}.json`),json('data/explorer_references.json'),json('GUIDED_QA.json')]);state.countries=countries;state.figures=list(figures.figures);state.dict=dict;state.references=refs;state.manifest=manifest;if(!countries.some(c=>c.code===state.country))state.country=countries.some(c=>c.code==='NLD')?'NLD':countries[0]?.code||'NLD';if(!new URLSearchParams(location.search).has('subject')&&route.question){if(countries.some(c=>c.code===route.country))state.country=route.country;const q=new URLSearchParams(location.search),f=state.figures.find(f=>f.question===route.question&&f.age===(q.get('age')||'age10')&&(f.domain===(q.get('domain')||'reading')||f.domain==='all')&&(!q.has('outcome')||f.outcome===q.get('outcome')));if(f)Object.assign(state,{subject:f.age+':'+(f.domain==='all'?'reading':f.domain),split:splitKey(f),statistic:statisticKey(f)});}bind();window.__learningOutcomesShell={state,refresh,selectFigure,choices,exportPayload};await refresh();}
init().catch(error=>{console.error(error);$('#figureHeading').textContent=text('Dashboard tijdelijk niet bereikbaar','Dashboard temporarily unavailable');$('#chartStage').innerHTML='<p>'+esc(text('Ververs de pagina om de bestanden opnieuw op te halen.','Refresh the page to load the files again.'))+'</p>';$('.figure-shell').setAttribute('aria-busy','false');});
